package com.quizrank.backend.controller;
import com.quizrank.backend.entity.*;import com.quizrank.backend.repository.*;import org.springframework.web.bind.annotation.*;import jakarta.validation.Valid;import jakarta.validation.constraints.*;import org.springframework.http.HttpStatus;import org.springframework.web.server.ResponseStatusException;import java.time.*;import java.util.*;
@RestController @RequestMapping("/api/notices") public class NoticeController {private final NoticeRepository r;private final UserRepository users;public NoticeController(NoticeRepository r,UserRepository u){this.r=r;users=u;}public record NoticeRequest(@NotNull Integer teacherId,Integer subjectId,@NotBlank String topic,@NotBlank String message,LocalDate quizDate,LocalTime quizTime){}@GetMapping public List<Notice> all(){return r.findAll();}@GetMapping("/teacher/{id}") public List<Notice> teacher(@PathVariable Integer id){return r.findByTeacherIdOrderByCreatedAtDesc(id);}@PostMapping public Notice create(@Valid @RequestBody NoticeRequest x){User t=users.findById(x.teacherId()).orElseThrow(()->new NoSuchElementException("Teacher not found"));if(t.getRole()!=User.Role.TEACHER)throw new IllegalArgumentException("Only teachers can post notices");Notice n=new Notice();n.setTeacherId(x.teacherId());n.setSubjectId(x.subjectId());n.setTopic(x.topic());n.setMessage(x.message());n.setQuizDate(x.quizDate());n.setQuizTime(x.quizTime());return r.save(n);}@PutMapping("/{id}") public Notice update(@PathVariable Integer id,@Valid @RequestBody NoticeRequest x){Notice n=r.findById(id).orElseThrow(()->new NoSuchElementException("Notice not found"));if(!n.getTeacherId().equals(x.teacherId()))throw new IllegalArgumentException("Only notice owner can update");n.setSubjectId(x.subjectId());n.setTopic(x.topic());n.setMessage(x.message());n.setQuizDate(x.quizDate());n.setQuizTime(x.quizTime());return r.save(n);}@DeleteMapping("/{id}") public Map<String,String> delete(@PathVariable Integer id){r.delete(r.findById(id).orElseThrow(()->new NoSuchElementException("Notice not found")));return Map.of("message","Notice deleted");}}
